// src/pages/Dashboard.jsx → VERSIÓN FINAL CORREGIDA Y ÉPICA
import { useNavigate } from "react-router-dom";
import { 
  Utensils, 
  Table, 
  ShoppingCart, 
  Package, 
  Users, 
  LogOut,
  Calendar,
  Flame
} from "lucide-react";
import "./Dashboard.css";

export default function Dashboard() {
  const navigate = useNavigate();

  const cerrarSesion = () => {
    localStorage.removeItem("access_token");
    localStorage.removeItem("refresh_token");
    navigate("/login");
  };

  const menu = [
    {
      titulo: "Mesas",
      subtitulo: "Control de ocupación",
      icon: Table,
      color: "#e74c3c",
      ruta: "/mesas"
    },
    {
      titulo: "Pedidos",
      subtitulo: "Gestión y seguimiento",
      icon: ShoppingCart,
      color: "#c0392b",
      ruta: "/pedidos"
    },
    {
      titulo: "Productos",
      subtitulo: "Menú del restaurante",
      icon: Utensils,
      color: "#e74c3c",
      ruta: "/productos"
    },
    {
      titulo: "Categorías",
      subtitulo: "Organización del menú",
      icon: Package,
      color: "#c0392b",
      ruta: "/categorias"
    },
    {
      titulo: "Empleados",
      subtitulo: "Gestión del personal",
      icon: Users,
      color: "#e74c3c",
      ruta: "/empleados"
    },
    {
      titulo: "Reportes",
      subtitulo: "Ventas y estadísticas",
      icon: Calendar,
      color: "#c0392b",
      ruta: "/reportes"
    },
    // ← BOTÓN DE COCINA EN VIVO 100% IGUAL QUE LOS DEMÁS
    {
      titulo: "COCINA EN VIVO",
      subtitulo: "Pantalla roja en tiempo real",
      icon: Flame,
      color: "#ff6b35",
      ruta: "/cocina",
      abrirEnPestana: true  // ← para abrir en nueva pestaña
    }
  ];

  return (
    <div className="dashboard">
      <div className="dashboard-bg"></div>
      <div className="dashboard-overlay"></div>

      <div className="dashboard-content">
        <div className="header">
          <h1 className="title">SOFTFOOD</h1>
          <p className="subtitle">Panel de Control del Restaurante</p>
        </div>

        <div className="grid">
          {menu.map((item, index) => {
            const Icon = item.icon;
            const handleClick = () => {
              if (item.abrirEnPestana) {
                window.open(item.ruta, "_blank");
              } else {
                navigate(item.ruta);
              }
            };

            return (
              <div
                key={index}
                className="card"
                onClick={handleClick}
                style={{ "--card-color": item.color }}
              >
                <div className="card-icon">
                  <Icon size={48} strokeWidth={1.8} />
                </div>
                <h3>{item.titulo}</h3>
                <p>{item.subtitulo}</p>
              </div>
            );
          })}
        </div>

        <button onClick={cerrarSesion} className="logout-btn">
          <LogOut size={20} />
          Cerrar Sesión
        </button>
      </div>
    </div>
  );
}
